<?php
namespace Tests\Feature;
use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ProspectingShellTest extends TestCase { use RefreshDatabase;
 public function test_prospecting_requires_authentication(): void { $this->get('/prospecting')->assertRedirect('/login'); }
 public function test_authenticated_prospecting_keeps_functional_panel_and_shell(): void { $r=$this->actingAs(User::factory()->create())->get('/prospecting');$r->assertOk()->assertSee('prospecting-shell-sidebar')->assertSee('prospecting-functional-panel')->assertSee('id="map"',false)->assertSee('id="search-form"',false)->assertSee('id="keyword"',false)->assertSee('id="jobs"',false)->assertSee('/app/app.js?v='.filemtime(public_path('app/app.js')),false)->assertSee('class="is-active"',false)->assertSee('scraper-shell.css?v=',false)->assertSee('prospecting-shell.css?v=',false);$this->assertStringNotContainsString('display:none!important;visibility:hidden!important',$r->getContent()); }
 public function test_prospecting_script_has_one_submit_handler_and_terminal_overlay_flow(): void { $script=file_get_contents(public_path('app/app.js'));$this->assertSame(1,substr_count($script,'$("#search-form").addEventListener("submit"'));$this->assertStringContainsString('if (!terms.length)',$script);$this->assertStringContainsString('setSearchProgress("Busca iniciada. Preparando a coleta…")',$script);$this->assertStringContainsString('["ok", "partial"].includes(j.status)',$script);$this->assertStringContainsString('state.activeJobId = null',$script);$this->assertStringContainsString('Ir para Leads',file_get_contents(resource_path('views/prospecting.html'))); }
}
